import sys
from collections import deque

d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
grid = d[2:2 + r]
cells = {(i, j) for i in range(r) for j in range(c) if grid[i][j] != '.'}
dist = {(0, 0): 0}
q = deque([(0, 0)])
while q:
    x, y = q.popleft()
    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
        if (nx, ny) in cells and (nx, ny) not in dist:
            dist[(nx, ny)] = dist[(x, y)] + 1
            q.append((nx, ny))
order = sorted(dist, key=lambda p: dist[p])
print(''.join(grid[x][y] for x, y in order if grid[x][y] != '*'))

