def gen(rng):
    R, C = 10, 15
    letters = 'abcdefghijklmnopqrstuvwxyz'

    def render(path, chars):
        g = [['.'] * C for _ in range(R)]
        for (x, y), ch in zip(path, chars):
            g[x][y] = ch
        return f'{R} {C}\n' + '\n'.join(''.join(row) for row in g)

    def walk(length):
        path = [(0, 0)]
        used = {(0, 0)}
        while len(path) < length:
            x, y = path[-1]
            opts = []
            for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                nx, ny = x + dx, y + dy
                if not (0 <= nx < R and 0 <= ny < C) or (nx, ny) in used:
                    continue
                ok = True
                for ex, ey in ((nx + 1, ny), (nx - 1, ny), (nx, ny + 1), (nx, ny - 1)):
                    if (ex, ey) in used and (ex, ey) != (x, y):
                        ok = False
                        break
                if ok:
                    opts.append((nx, ny))
            if not opts:
                break
            nxt = rng.choice(opts)
            path.append(nxt)
            used.add(nxt)
        return path

    def chars_for(n, p):
        cs = [rng.choice(letters) if rng.random() < p else '*' for _ in range(n)]
        if all(ch == '*' for ch in cs):
            cs[rng.randrange(n)] = rng.choice(letters)
        return cs

    tests = []
    tests.append(render([(0, 0), (0, 1)], ['a', 'b']))
    tests.append(render([(0, 0), (0, 1)], ['*', 'z']))
    tests.append(render([(0, 0), (1, 0)], ['q', '*']))
    # serpentine path covering most of the grid
    snake = []
    for row in range(0, 9, 2):
        cols = range(C) if row % 4 == 0 else range(C - 1, -1, -1)
        for col in cols:
            snake.append((row, col))
        if row < 8:
            snake.append((row + 1, C - 1 if row % 4 == 0 else 0))
    tests.append(render(snake, chars_for(len(snake), 0.5)))
    tests.append(render(snake, chars_for(len(snake), 1.0)))
    tests.append(render(snake, ['*'] * (len(snake) - 1) + ['m']))
    for _ in range(30):
        n = rng.randint(2, 90)
        path = walk(n)
        if len(path) < 2:
            continue
        tests.append(render(path, chars_for(len(path), rng.choice([0.2, 0.5, 0.9]))))
    return tests

